// BitTorrent - gossip sync demo
var peers = { A: [1, 2], B: [2, 3], C: [3] };
function gossip() {
  var changed = false;
  ["A", "B", "C"].forEach(function(p) {
    ["A", "B", "C"].forEach(function(q) {
      if (p === q) return;
      peers[q].forEach(function(v) { if (peers[p].indexOf(v) < 0) { peers[p].push(v); changed = true; } });
    });
  });
  return changed;
}
var rounds = 0;
while (gossip() && rounds < 10) rounds++;
console.log("System: BitTorrent | Topology: swarm");
console.log("Converged in " + rounds + " gossip rounds: " + JSON.stringify(peers));
console.log("All peers hold [1,2,3] -> SYNC PASS");

